@strawberry.type
class Query:
    @strawberry.field
    async def business_credit_line(self, info: Info, id: uuid.UUID) -> Optional[CreditLineType]:
        user = info.context.get("current_user")
        if not user:
            raise HTTPException(status_code=401, detail="Authentication required")

        loader: DataLoader = info.context["credit_line_loader"]
        record = await loader.load(id)
        if not record:
            return None

        if record.business_id != user.business_id and not user.is_risk_officer:
            raise HTTPException(status_code=403, detail="Forbidden: unauthorized to view credit line details")

        return CreditLineType(
            id=record.id,
            credit_limit=record.limit_amount,
            utilized_balance=record.utilized_amount,
            interest_rate=record.interest_rate
        )
